const SpeakingIcon = ({ emoji }: { emoji: string }) => (
  <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', margin: '1rem 0', justifyContent: 'center' }}>
    {/* Person icon */}
    <WormIcon />

    {/* Speech bubble */}
    <div style={{
      position: 'relative',
      background: '#fff',
      borderRadius: '10px',
      padding: '0.5rem 1rem',
      border: '2px solid #FFD93B',
      fontSize: '2rem',
      color: '#333',
      boxShadow: '2px 2px 5px rgba(0,0,0,0.1)'
    }}>
      {emoji}
      <div style={{
        position: 'absolute',
        left: '-10px',
        top: '50%',
        transform: 'translateY(-50%)',
        width: 0,
        height: 0,
        borderTop: '10px solid transparent',
        borderBottom: '10px solid transparent',
        borderRight: '10px solid #fff'
      }}></div>
    </div>
  </div>
);

const LockedIcon = () => (
  <svg width="50" height="50" viewBox="0 0 100 100">
    <circle cx="50" cy="50" r="45" fill="#dbe9f4" stroke="#7baad3" strokeWidth="5" />
    <rect x="40" y="40" width="20" height="30" rx="5" fill="#7baad3" />
    <circle cx="50" cy="60" r="3" fill="#fff" />
  </svg>
);

const UnlockedIcon = () => (
  <svg width="50" height="50" viewBox="0 0 100 100">
    <circle cx="50" cy="50" r="45" fill="#ffe29a" stroke="#f7c948" strokeWidth="5" />
    <polygon points="50,30 55,45 70,45 58,55 63,70 50,60 37,70 42,55 30,45 45,45" fill="#fff" />
  </svg>
);

const BackArrowIcon = () => (
  <svg width="30" height="30" viewBox="0 0 24 24">
    <path fill="#000" d="M15.41 7.41L14 6l-6 6 6 6 1.41-1.41L10.83 12z" />
  </svg>
);

type GameScreen = 'map' | 'puzzle';

const words = ['CAR', 'DOG', 'SUN'];
const images = ['🚗', '🐶', '☀️'];

const App = () => {
  const [screen, setScreen] = useState<GameScreen>('map');
  const [currentLevel, setCurrentLevel] = useState(0);
  const [userInput, setUserInput] = useState<string[]>([]);
  const [completedLevels, setCompletedLevels] = useState<number[]>([]);
  const [showConfetti, setShowConfetti] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);

  const currentWord = words[currentLevel];
  const currentImage = images[currentLevel];
  const shuffledLetters = [...currentWord.split('')].sort(() => Math.random() - 0.5);

  const handleLetterClick = (letter: string) => {
    if (userInput.length < currentWord.length) {
      setUserInput([...userInput, letter]);
    }
  };

  useEffect(() => {
    if (userInput.length === currentWord.length) {
      if (userInput.join('') === currentWord) {
        setShowConfetti(true);
        setShowSuccess(true);
        if (!completedLevels.includes(currentLevel)) {
          setCompletedLevels([...completedLevels, currentLevel]);
        }
      }
    }
  }, [userInput]);

  const resetPuzzle = () => {
    setUserInput([]);
    setShowConfetti(false);
    setShowSuccess(false);
  };

  const continueToMap = () => {
    setShowConfetti(false);
    setShowSuccess(false);
    if (currentLevel < words.length - 1) {
      setCurrentLevel(currentLevel + 1);
    }
    setUserInput([]);
    setScreen('map');
  };

  const closeModal = () => {
    setShowConfetti(false);
    setShowSuccess(false);
  };

  const goBackToMap = () => {
    setScreen('map');
    setUserInput([]);
  };

  const containerStyle: CSSProperties = {
    fontFamily: "'Inter', sans-serif",
    background: 'linear-gradient(to top, #87c145, #E3E075)',
    minHeight: '100vh',
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'flex-start',
    padding: '2rem',
  };

  const buttonStyle: CSSProperties = {
    borderRadius: '20px',
    padding: '0px 24px',
    margin: '0.5rem',
    boxShadow: '0 4px 6px rgba(0,0,0,0.1)',
    cursor: 'pointer',
    border: 'none',
    fontSize: '3.2rem',
    fontWeight: 'bold',
    transition: 'transform 0.2s ease, box-shadow 0.2s ease',
    background: '#FEF8E2',
    color: '#f56d40',
  };

  const replayButtonStyle: CSSProperties = {
    ...buttonStyle,
    fontSize: '2rem',
    background: 'linear-gradient(to right, #FBEA82, #FBEA82)',
    color: '#CE682A',
    // transform: 'translate(-50%, 70px)',
    // position: 'absolute',
    // border: '6px solid #FBEA82'
  };

  const continueButtonStyle: CSSProperties = {
    ...buttonStyle,
    fontSize: '2rem',
    background: 'linear-gradient(to right, #B4FDBB, #B4FDBB)',
    color: '#2B7C20',
    // transform: 'translate(50%, 70px)',
    // position: 'absolute',
    // border: '6px solid #B4FDBB'
  };

  const progressIconStyle: CSSProperties = {
    width: '50px',
    height: '50px',
    margin: '0 10px',
    cursor: 'pointer',
    transition: 'transform 0.2s ease',
    zIndex: 2,
  };

  const progressLineStyle: CSSProperties = {
    position: 'absolute',
    top: '50%',
    left: '10px',
    right: '10px',
    height: '4px',
    background: '#ffe29a',
    zIndex: 1,
  };

  const handleIconClick = (index: number) => {
    if (index <= currentLevel) {
      setCurrentLevel(index);
      setUserInput([]);
      setScreen('puzzle');
    }
  };

  const score = 100;

  return (
    <div style={containerStyle}>
      {showConfetti && <Confetti />}

      {screen === 'map' && (
        <div style={{ position: 'relative', marginBottom: '2rem', display: 'flex', alignItems: 'center' }}>
          <div style={progressLineStyle}></div>
          {words.map((_, idx) => {
            const isUnlocked = idx <= currentLevel || completedLevels.includes(idx);
            const Icon = isUnlocked ? UnlockedIcon : LockedIcon;
            return (
              <motion.div
                key={idx}
                whileHover={{ scale: 1.2 }}
                style={{ ...progressIconStyle, opacity: isUnlocked ? 1 : 0.5 }}
                onClick={() => isUnlocked && handleIconClick(idx)}
              >
                <Icon />
              </motion.div>
            );
          })}
        </div>
      )}

      <AnimatePresence mode="wait">
        {screen === 'puzzle' && (
          <motion.div
            key="puzzle"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            style={{ textAlign: 'center', width: '100%' }}
          >
            <button
              onClick={goBackToMap}
              style={{ background: 'transparent', border: 'none', cursor: 'pointer', marginBottom: '1rem', display: 'flex' }}
            >
              <BackArrowIcon/>
            </button>

            {!showSuccess && (
              <>
                <div style={{ display: 'flex', justifyContent: 'center', gap: '1rem', flexWrap: 'wrap' }}>
                  {shuffledLetters.map((letter, index) => (
                    <motion.button
                      key={index}
                      whileTap={{ scale: 1.2 }}
                      whileHover={{ scale: 1.1, boxShadow: '0 0 10px rgba(0,0,0,0.2)' }}
                      onClick={() => handleLetterClick(letter)}
                      style={buttonStyle}
                    >
                      {letter}
                    </motion.button>
                  ))}
                </div>

                <div style={{ display: 'flex', justifyContent: 'center', marginTop: '1rem', gap: '0.5rem' }}>
                  {currentWord.split('').map((_, idx) => (
                    <div
                      key={idx}
                      style={{
                        minWidth: '30px',
                        borderBottom: '2px solid black',
                        fontSize: '1.5rem',
                        color: '#f56d40',
                        textAlign: 'center',
                      }}
                    >
                      {userInput[idx] || ' '}
                    </div>
                  ))}
                </div>

                {userInput.length === currentWord.length && userInput.join('') !== currentWord && (
                  <motion.button
                    whileHover={{ scale: 1.1, boxShadow: '0 0 10px rgba(0,0,0,0.2)' }}
                    onClick={resetPuzzle}
                    style={{ ...buttonStyle, background: '#f56d40', color: '#fff' }}
                  >
                    Clear
                  </motion.button>
                )}
              </>
            )}

            {showSuccess && (
              <motion.div
                initial={{ scale: 0 }}
                animate={{ scale: 1 }}
                transition={{ type: 'spring', stiffness: 300 }}
                style={{
                  position: 'fixed',
                  top: 0, left: 0, right: 0, bottom: 0,
                  background: 'rgba(0,0,0,0.5)',
                  display: 'flex',
                  justifyContent: 'center',
                  alignItems: 'center',
                  zIndex: 999
                }}
              >
                <motion.div
                  initial={{ opacity: 0, y: 50 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ type: 'spring', stiffness: 300 }}
                  style={{
                    background: '#E3ECFC',
                    borderRadius: '20px',
                    padding: '2rem',
                    textAlign: 'center',
                    boxShadow: '0 4px 20px rgba(0,0,0,0.2)',
                    minWidth: '300px',
                    position: 'relative',
                    overflow: 'visible',
                    border: '6px solid #77A8FD'
                  }}
                >
                  <div style={{
                    position: 'absolute',
                    top: '-20px',
                    left: '50%',
                    transform: 'translate(-50%, -50%)',
                    zIndex: 1000
                  }}>
                    <PerfectIcon />
                  </div>

                  <button
                    onClick={closeModal}
                    style={{
                      position: 'absolute',
                      top: '10px',
                      right: '10px',
                      background: 'transparent',
                      color: 'black',
                      border: 'none',
                      fontSize: '1.5rem',
                      cursor: 'pointer'
                    }}
                  >
                    ✖
                  </button>

                  <div style={{ fontSize: '2rem', color: '#FF6F61', marginBottom: '1rem' }}>
                    {score >= 100 ? 'Perfect!' : score >= 50 ? 'Great Job!' : 'Good Try!'}
                  </div>

                  <div style={{ fontSize: '3rem', fontWeight: 'bold', color: '#3366FF', marginBottom: '1.5rem' }}>
                    🎉 {score} Points!
                  </div>

                  <motion.button
                    whileHover={{ scale: 1.1, boxShadow: '0 0 10px rgba(0,0,0,0.2)' }}
                    onClick={resetPuzzle}
                    style={replayButtonStyle}
                  >
                    Play Again
                  </motion.button>

                  <motion.button
                    whileHover={{ scale: 1.1, boxShadow: '0 0 10px rgba(0,0,0,0.2)' }}
                    onClick={continueToMap}
                    style={{ ...continueButtonStyle, marginLeft: '1rem' }}
                  >
                    Continue
                  </motion.button>
                </motion.div>
              </motion.div>
            )}

            <div>
              
              <SpeakingIcon emoji={currentImage} />

            </div>

          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default App;


